package com.lamggm.rospocket;
import android.view.*;import android.widget.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=31,qualifiers="w1000dp-h700dp") @LooperMode(LooperMode.Mode.PAUSED)
public class OperatorHeaderTest {
 final ConnectionActivityTest f=new ConnectionActivityTest();
 @Before public void setup()throws Exception{f.setup();f.controller.visible();f.paint();}
 @After public void cleanup()throws Exception{f.cleanup();}
 @Test public void robotTitleBelongsToGlobalHeaderAndUsesHonestConnectionFallbacks()throws Exception{
  TextView title=(TextView)f.get("dashboardTitle");f.call("disconnect",new Class<?>[]{});f.call("refreshDashboard",new Class<?>[]{});assertEquals("desconectado",title.getText().toString());assertFalse(isWithin(title,f.a.findViewById(R.id.section_monitor)));
  f.set("connectWanted",true);f.set("dashboardPeers",1);f.call("refreshDashboard",new Class<?>[]{});assertEquals("desconhecido",title.getText().toString());f.a.findViewById(R.id.nav_location).performClick();assertTrue(title.isShown());
 }
 @Test public void appliedProfileIsSeparateFromRobotIdentityAndShowsUnsavedEdits()throws Exception{f.call("disconnect",new Class<?>[]{});f.a.findViewById(R.id.profile_new).performClick();((EditText)f.a.findViewById(R.id.profile_name)).setText("Perfil-Bancada");f.a.findViewById(R.id.profile_save).performClick();f.paint();f.a.findViewById(R.id.profile_apply).performClick();f.paint();f.call("refreshDashboard",new Class<?>[]{});TextView badge=f.a.getWindow().getDecorView().findViewWithTag("applied-profile");assertTrue(badge.getText().toString().contains("Perfil-Bancada"));assertEquals("desconectado",((TextView)f.get("dashboardTitle")).getText().toString());((EditText)f.a.findViewById(R.id.peer)).setText("192.0.2.9");f.call("refreshDashboard",new Class<?>[]{});assertTrue(badge.getText().toString(),badge.getText().toString().contains("não salva"));f.a.getWindow().getDecorView().findViewWithTag("dashboard-edit").performClick();f.call("refreshDashboard",new Class<?>[]{});assertTrue(badge.getText().toString(),badge.getText().toString().contains("painel em edição"));}
 @Test public void observedUrdfNameAppearsCenteredAndRetiresOnDisconnect()throws Exception{RobotContext c=(RobotContext)f.get("robotContext");RobotContext.Snapshot s=c.observe(new RobotTfContextTest.Api(),96,"127.0.0.1","","lan","jazzy",RobotTfContextTest.topics(),()->true);assertNotNull(s.model);f.set("dashboardPeers",1);((RobotPanel)f.get("robotPanel")).update(s);f.call("refreshDashboard",new Class<?>[]{});TextView title=(TextView)f.get("dashboardTitle");assertEquals(s.model.name,title.getText().toString());assertEquals(android.view.Gravity.CENTER_HORIZONTAL,title.getGravity()&android.view.Gravity.HORIZONTAL_GRAVITY_MASK);View root=f.a.getWindow().getDecorView().findViewWithTag("app-root");root.measure(View.MeasureSpec.makeMeasureSpec(1000,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(700,View.MeasureSpec.EXACTLY));root.layout(0,0,1000,700);f.call("refreshDashboard",new Class<?>[]{});int[] point=new int[2];title.getLocationOnScreen(point);assertEquals(500,point[0]+title.getWidth()/2,1);TextView brand=root.findViewWithTag("brand-title");int[] b=new int[2];brand.getLocationOnScreen(b);assertEquals(b[1]+brand.getBaseline(),point[1]+title.getBaseline(),1);f.call("disconnect",new Class<?>[]{});f.call("refreshDashboard",new Class<?>[]{});assertEquals("desconectado",title.getText().toString());}
 @Test public void addReadingIsAnAccessibleFloatingPlusNotAHeadingButton(){View root=f.a.getWindow().getDecorView().findViewWithTag("app-root");Button add=root.findViewWithTag("add-reading");assertEquals("+",add.getText().toString());assertEquals("Adicionar leitura",add.getContentDescription());assertTrue(add.getParent() instanceof FrameLayout);f.a.findViewById(R.id.nav_location).performClick();assertEquals(View.GONE,add.getVisibility());}
 private boolean isWithin(View v,View ancestor){for(android.view.ViewParent p=v.getParent();p instanceof View;p=p.getParent())if(p==ancestor)return true;return false;}
}
